/* Bancada de engenharia reversa do MS Project, medida no Project Professional 2019 real.
 *
 * Cada cenário descreve um cronograma pequeno e o que o Project calculou para ele, com "as tarefas
 * sempre respeitam as datas de restrição" ligado, "dividir tarefas em andamento" ligado e folga
 * crítica = 0. Os valores esperados de todas as tarefas vieram do próprio Project, montando o
 * cenário tarefa a tarefa por automação (scripts/ms-project/montar-no-project.ps1); para tarefa em
 * andamento, abrindo o .xml exportado (abrir-xml.ps1), que guarda o estado como o sistema guarda.
 * Ver docs/engenharia-reversa-project.md, seção "Conferência no Project real".
 *
 * Datas são o dia que a tabela do Project mostra. O Project trabalha em instantes (08:00 e 17:00):
 * uma tarefa que termina às 08:00 de segunda aparece com término na segunda. Calendário: segunda a
 * sexta, sem feriados salvo quando indicado; 2026-09-07 é segunda-feira. Durações em dias úteis
 * ("d") ou corridos ("dd"); 0 é marco. Folgas em dias úteis; nas tarefas em dias corridos, em dias
 * corridos de 24 h (do fim de um dia ao começo do seguinte são 15 h = 0,625). Os cenários com
 * prefixo (X, F, V) foram criados na conferência para isolar uma regra cada. */

export type Restricao = 'ASAP' | 'ALAP' | 'SNET' | 'SNLT' | 'FNET' | 'FNLT' | 'MSO' | 'MFO';
export interface TarefaCenario {
  id: string;
  dur: string;
  /** Início digitado quando não há predecessora (vale como o início guardado no plano). */
  inicio?: string;
  nivel?: number;
  restricao?: { tipo: Restricao; data?: string };
  prazo?: string;
  inicioReal?: string;
  terminoReal?: string;
  progresso?: number;
}
export interface VinculoCenario {
  de: string;
  para: string;
  tipo?: 'TI' | 'II' | 'TT' | 'IT';
  lag?: number;
  corrido?: boolean;
}
export interface Esperado {
  inicio?: string;
  termino?: string;
  inicioTardio?: string;
  terminoTardio?: string;
  folgaTotal?: number;
  folgaLivre?: number;
  critica?: boolean;
  /** Vínculo ou restrição desrespeitados (o Project mostra folga negativa e o aviso de conflito). */
  conflito?: boolean;
  prazoPerdido?: boolean;
  /** Ids das predecessoras que de fato mandam na data ("predecessoras determinantes"). */
  determinantes?: string[];
}
export interface Cenario {
  nome: string;
  feriados?: string[];
  tarefas: TarefaCenario[];
  vinculos?: VinculoCenario[];
  esperado: Record<string, Esperado>;
  nota?: string;
}

